func (o offerDo) ScanByPage(result interface{}, offset int, limit int) (count int64, err error) {
	count, err = o.Count()
	if err != nil {
		return
	}

	err = o.Offset(offset).Limit(limit).Scan(result)
	return
}

func (o offerDo) Scan(result interface{}) (err error) {
	return o.DO.Scan(result)
}

func (o offerDo) Delete(models ...*models.Offer) (result gen.ResultInfo, err error) {
	return o.DO.Delete(models)
}

func (o *offerDo) withDO(do gen.Dao) *offerDo {
	o.DO = *do.(*gen.DO)
	return o
}
